 "content": "from collections import deque


def _components(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    out = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if (0 <= yy < h and 0 <= xx < w and
                            (yy, xx) not in seen and grid[yy][xx] == color):
                        seen.add((yy, xx))
                        q.append((yy, xx))
            out.append((color, cells))
    return out


def _shape(cells):
    minr = min(r for r, c in cells)
    minc = min(c for r, c in cells)
    return frozenset((r - minr, c - minc) for r, c in cells)


def transform(grid):
    result = [row[:] for row in grid]
    comps = _components(grid)
    templates = {}
    for color, cells in comps:
        if color != 1:
            templates.setdefault(_shape(cells), color)
    for color, cells in comps:
        if color == 1:
            target = templates.get(_shape(cells))
            if target is not None:
                for r, c in cells:
                    result[r][c] = target
    return result
